/* 时空猪 · 像素图标。由 tools/embed-icons.mjs 根据 assets/icons 生成。 */
(function (global) {
  'use strict';
  var SP = global.SP || (global.SP = {});

  var URLS = {
    'alpha': 'data:image/png;base64,',
    'amulet': 'data:image/png;base64,',
    'axe': 'data:image/png;base64,',
    'bow': 'data:image/png;base64,',
    'circlet': 'data:image/png;base64,',
    'coinring': 'data:image/png;base64,',
    'dagger': 'data:image/png;base64,',
    'flail': 'data:image/png;base64,',
    'greaves': 'data:image/png;base64,',
    'hood': 'data:image/png;base64,',
    'hunterband': 'data:image/png;base64,',
    'ironhelm': 'data:image/png;base64,',
    'lightboots': 'data:image/png;base64,',
    'maul': 'data:image/png;base64,',
    'mob-alpha': 'data:image/png;base64,',
    'mob-bat': 'data:image/png;base64,',
    'mob-broodling': 'data:image/png;base64,',
    'mob-calf': 'data:image/png;base64,',
    'mob-charger': 'data:image/png;base64,',
    'mob-crawler': 'data:image/png;base64,',
    'mob-gargoyle': 'data:image/png;base64,',
    'mob-golem': 'data:image/png;base64,',
    'mob-queen': 'data:image/png;base64,',
    'mob-ravager': 'data:image/png;base64,',
    'mob-shardcaster': 'data:image/png;base64,',
    'mob-spitter': 'data:image/png;base64,',
    'mob-sporeling': 'data:image/png;base64,',
    'mob-thornbeast': 'data:image/png;base64,',
    'mob-treant': 'data:image/png;base64,',
    'mob-venomwing': 'data:image/png;base64,',
    'pendant': 'data:image/png;base64,',
    'plate': 'data:image/png;base64,',
    're': 'data:image/png;base64,',
    'robe': 'data:image/png;base64,',
    'signet': 'data:image/png;base64,',
    'spear': 'data:image/png;base64,',
    'staff': 'data:image/png;base64,',
    'steak': 'data:image/png;base64,',
    'sword': 'data:image/png;base64,',
    'up': 'data:image/png;base64,',
    'vest': 'data:image/png;base64,'
  };

  /** 空槽、以及旧存档里没有 base 字段时，用这个部位的代表图标 */
  var FALLBACK = {
    weapon: 'sword', helm: 'ironhelm', armor: 'vest', boots: 'lightboots',
    amulet: 'amulet', ring: 'coinring', ring1: 'coinring', ring2: 'signet'
  };

  var cache = {};
  function url(key) { return URLS[key] || null; }
  function image(key) {
    var u = url(key);
    if (!u || typeof Image === 'undefined') return null;
    if (!cache[key]) {
      var img = new Image();
      img.src = u;
      cache[key] = img;
    }
    return cache[key];
  }
  function forItem(item) {
    if (item && item.base && URLS[item.base]) return item.base;
    if (item && item.slot && FALLBACK[item.slot]) return FALLBACK[item.slot];
    return null;
  }
  /** 怪物图鉴：assets/icons/icon-mob-<enemyKey>.png */
  function forEnemy(enemyKey) {
    if (!enemyKey) return null;
    var k = 'mob-' + enemyKey;
    return URLS[k] ? k : null;
  }
  function enemyUrl(enemyKey) {
    var k = forEnemy(enemyKey);
    return k ? url(k) : null;
  }

  if (typeof Image !== 'undefined') {
    Object.keys(URLS).forEach(function (k) { image(k); });
  }

  SP.ItemIcons = {
    url: url, image: image, fallback: FALLBACK,
    forItem: forItem, forEnemy: forEnemy, enemyUrl: enemyUrl
  };
  SP.EnemyIcons = { url: enemyUrl, forEnemy: forEnemy };
})(typeof window !== 'undefined' ? window : globalThis);
